from typing import List

def separate_paren_groups(paren_string: str) -> List[str]:
    result = []
    current = ''
    depth = 0
    for c in paren_string:
        if c == '(':
            depth += 1
        elif c == ')':
            depth -= 1
        if c != ' ':
            current += c
        if depth == 0 and current:
            result.append(current)
            current = ''
    return result
